public final class ClassFileReader {
    private final byte[] classFileBuffer;

    public ClassFileReader(byte[] classFileBuffer) {
        this.classFileBuffer = classFileBuffer;
    }

    public String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
            throw new IllegalArgumentException("Invalid constant pool entry index");
        }

        int utf8Length = classFileBuffer[constantPoolEntryIndex + 1];
        if (utf8Length == 0) {
            return "";
        }

        int utf8Offset = constantPoolEntryIndex + 2;
        int utf8End = utf8Offset + utf8Length;

        if (utf8End > classFileBuffer.length) {
            throw new IllegalArgumentException("UTF-8 string is too long");
        }

        int utf8Index = utf8Offset;
        int utf8LengthRead = 0;

        while (utf8Index < utf8End) {
            int byteValue = classFileBuffer[utf8Index];
            if ((byteValue & 0x80) == 0) {
                charBuffer[utf8LengthRead++] = (char) byteValue;
                utf8Index++;
            } else {
                int continuationByte = byteValue & 0x7F;
                if (utf8Index + 1 >= utf8End) {
                    throw new IllegalArgumentException("Invalid UTF-8 string");
                }
                byte continuationByte2 = classFileBuffer[utf8Index + 1];
                charBuffer[utf8LengthRead++] = (char) ((continuationByte << 6) | continuationByte2);
                utf8Index += 2;
            }
        }

        return new String(charBuffer, 0, utf8LengthRead, StandardCharsets.UTF_8);
    }
