    while (end < buf.length() && Character.isLetterOrDigit(buf.charAt(end))) {
        end++;
    }

    if (end - nameStart > 3) {
        buf.append(nameStart).append(end - nameStart).append(" ");
    } else {
        buf.append(nameStart).append(end - nameStart);
    }
}

